package com.pulseride.admin.config;
import java.nio.charset.StandardCharsets; import javax.crypto.spec.SecretKeySpec; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.oauth2.jwt.*; import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationConverter; import org.springframework.security.web.SecurityFilterChain;
@Configuration @EnableMethodSecurity public class SecurityConfig { @Bean SecretKeySpec key(@Value("${jwt.secret}")String s){return new SecretKeySpec(s.getBytes(StandardCharsets.UTF_8),"HmacSHA256");} @Bean JwtDecoder decoder(SecretKeySpec k,@Value("${jwt.issuer}")String i){var d=NimbusJwtDecoder.withSecretKey(k).build();d.setJwtValidator(JwtValidators.createDefaultWithIssuer(i));return d;} @Bean JwtAuthenticationConverter converter(){var c=new JwtAuthenticationConverter();c.setJwtGrantedAuthoritiesConverter(j->java.util.List.of(new org.springframework.security.core.authority.SimpleGrantedAuthority("ROLE_"+j.getClaimAsString("role"))));return c;} @Bean SecurityFilterChain filter(HttpSecurity h,JwtAuthenticationConverter c)throws Exception{return h.csrf(x->x.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.anyRequest().authenticated()).oauth2ResourceServer(o->o.jwt(j->j.jwtAuthenticationConverter(c))).build();} }
